package com.xirctwerk.vfx.client;

import com.google.gson.*;
import com.xirctwerk.vfx.core.*;
import com.xirctwerk.vfx.api.render.*;
import imgui.ImGui;
import imgui.type.*;
import imgui.flag.ImGuiSliderFlags;
import java.util.*;

/** Separate shader authoring workspace. Canonical data only; no imported shader execution. */
final class MaterialEditor {
    final ImBoolean open=new ImBoolean(false);private final ImString name=new ImString("new_material",64);private JsonObject json=Material.empty();private final Deque<JsonObject> undo=new ArrayDeque<>(),redo=new ArrayDeque<>();private RenderPipeline preview;private int shape,inspect;private boolean world,playing=true,before,editing;private float clock;private long last;private String status="";
    private void edit(java.util.function.Consumer<JsonObject> change){var copy=json.deepCopy();change.accept(copy);Material.compile(copy);if(copy.equals(json))return;if(!editing||!ImGui.isItemActive()||ImGui.isItemActivated())undo.push(json);editing=ImGui.isItemActive();while(undo.size()>50)undo.removeLast();redo.clear();json=copy;if(world)RenderEffects.world(Material.compile(json));}
    void close(){world=false;RenderEffects.world(null);if(preview!=null){preview.close();preview=null;}}
    void render(EffectFiles files){if(!ImGui.isAnyItemActive())editing=false;if(!open.get()){if(world||preview!=null)close();return;}ImGui.setNextWindowSize(Math.min(900,ImGui.getIO().getDisplaySizeX()-40),Math.min(650,ImGui.getIO().getDisplaySizeY()-40),imgui.flag.ImGuiCond.Appearing);ImGui.setNextWindowPos(20,30,imgui.flag.ImGuiCond.Appearing);if(ImGui.begin("Materials / Shaders",open))try{
        ImGui.columns(2,"Material workspace columns",true);ImGui.setColumnWidth(0,Math.max(260,ImGui.getWindowWidth()*.48f));try{
        if(ImGui.beginCombo("Surface",List.of("Plane","Sphere","Cube").get(shape))){for(int i=0;i<3;i++)if(ImGui.selectable(List.of("Plane","Sphere","Cube").get(i),i==shape))shape=i;ImGui.endCombo();}
        if(ImGui.checkbox("Play animation",playing))playing=!playing;ImGui.sameLine();if(ImGui.checkbox("Original",before))before=!before;
        long now=System.nanoTime();if(playing&&last!=0)clock=(clock+Math.min(.1f,(now-last)/1e9f))%5;last=now;float[] time={clock};if(ImGui.sliderFloat("Time",time,0,5,"%.2f s",ImGuiSliderFlags.AlwaysClamp)){clock=time[0];playing=false;}EditorHints.tip("Amount keys use normalized time 0..1 across this five second preview cycle. Runtime callers choose their own clock.");
        if(ImGui.checkbox("World preview",world)){world=!world;sync();}EditorHints.tip("Explicit full world post-processing preview, including VFX and bloom. Closing this workspace clears it.");
        if(ImGui.beginCombo("Buffer",inspect==0?"Final output":"Latest intermediate "+inspect)){for(int i=0;i<=(preview==null?0:preview.intermediateTextures().size());i++)if(ImGui.selectable(i==0?"Final output":"Latest intermediate "+i,inspect==i))inspect=i;ImGui.endCombo();}
        if(preview==null)preview=new RenderPipeline();int raw=preview.preview(512,384,shape,clock),texture=preview.render(raw,0,512,384,Material.compile(json),clock,clock/5.);if(before)texture=preview.preview(512,384,shape,clock);else if(inspect>0){if(inspect<=preview.intermediateTextures().size())texture=preview.intermediateTextures().get(inspect-1);else inspect=0;}
        float width=Math.min(Math.min(512,Math.max(64,ImGui.getContentRegionAvailX())),Math.max(120,ImGui.getContentRegionAvailY()-32)*4/3f);ImGui.image(texture,width,width*.75f,0,1,1,0);ImGui.textDisabled(String.format(Locale.ROOT,"GPU stack %.3f ms | %d / 16 nodes",preview.gpuMillis(),json.getAsJsonArray("nodes").size()));
        ImGui.nextColumn();ImGui.beginChild("Material inspector",0,0,false);try{
        ImGui.textWrapped("Add operations, tune their strength, then save a reusable material.");
        if(ImGui.button("New material"))edit(o->{o.remove("nodes");o.add("nodes",new JsonArray());});ImGui.sameLine();if(ImGui.button("Undo")&&!undo.isEmpty()){redo.push(json);json=undo.pop();sync();}ImGui.sameLine();if(ImGui.button("Redo")&&!redo.isEmpty()){undo.push(json);json=redo.pop();sync();}
        if(ImGui.beginCombo("Material presets","Choose...")){for(String preset:Material.PRESETS)if(ImGui.selectable(preset)){var loaded=Material.preset(preset);edit(o->o.add("nodes",loaded.get("nodes").deepCopy()));name.set(preset);}ImGui.endCombo();}
        ImGui.inputText("Material name",name);if(ImGui.button("Save / export JSON")){files.saveMaterial(name.get(),json);status="Saved materials/"+name.get()+".json";}EditorHints.tip("Validated data-only material in the Studio project folder. Safe to load on either loader.");ImGui.sameLine();if(ImGui.button("Load JSON")){var loaded=files.loadMaterial(name.get());edit(o->{o.remove("nodes");o.add("nodes",loaded.get("nodes").deepCopy());});status="Loaded material.";}
        if(ImGui.beginCombo("Add operation","Choose...")){for(String op:Material.OPERATIONS)if(ImGui.selectable(op)&&json.getAsJsonArray("nodes").size()<16)edit(o->o.getAsJsonArray("nodes").add(Material.node(op)));ImGui.endCombo();}
        var nodes=json.getAsJsonArray("nodes");for(int i=0;i<nodes.size();i++){final int index=i;var n=nodes.get(i).getAsJsonObject();ImGui.pushID(i);if(ImGui.collapsingHeader((i+1)+" -> "+n.get("operation").getAsString())){
            boolean enabled=!n.has("enabled")||n.get("enabled").getAsBoolean();if(ImGui.checkbox("Enabled",enabled))edit(o->o.getAsJsonArray("nodes").get(index).getAsJsonObject().addProperty("enabled",!enabled));
            String operation=n.get("operation").getAsString();for(String field:switch(operation){case "scroll"->List.of("amount","speed");case "gradient"->List.of("amount");case "distortion"->List.of("amount","speed","scale");default->List.of("amount","scale");}){float lo=field.equals("speed")?-10:field.equals("scale")?1:0,hi=field.equals("speed")?10:field.equals("scale")?64:1;float[] v={n.has(field)?n.get(field).getAsFloat():field.equals("amount")?.5f:field.equals("speed")?1:8};if(ImGui.sliderFloat(field,v,lo,hi,"%.3f",ImGuiSliderFlags.AlwaysClamp))edit(o->o.getAsJsonArray("nodes").get(index).getAsJsonObject().addProperty(field,v[0]));EditorHints.limits(lo,hi);EditorHints.tip(field.equals("amount")?"Operation strength. Authored keys override this constant while animation plays.":field.equals("speed")?"Animation speed; negative values reverse motion.":"Operation size in pixels, noise frequency or pattern scale.");}
            var c=n.has("color")?n.getAsJsonArray("color"):JsonParser.parseString("[0.55,0.25,1,1]").getAsJsonArray();float[] rgba=new float[4];for(int k=0;k<4;k++)rgba[k]=c.get(k).getAsFloat();if(Set.of("outline","fresnel","gradient").contains(operation)&&ImGui.colorEdit4("Tint / mask opacity",rgba,imgui.flag.ImGuiColorEditFlags.Float))edit(o->{var a=new JsonArray();for(float v:rgba)a.add(v);o.getAsJsonArray("nodes").get(index).getAsJsonObject().add("color",a);});
            if(ImGui.button("Key amount here"))edit(o->{var node=o.getAsJsonArray("nodes").get(index).getAsJsonObject();var keys=node.has("keys")?node.getAsJsonArray("keys"):new JsonArray();double t=Math.round(clock/5.*1000)/1000.;var sorted=new TreeMap<Double,JsonObject>();for(var k:keys){var key=k.getAsJsonObject();sorted.put(key.get("time").getAsDouble(),key);}var key=new JsonObject();key.addProperty("time",t);key.addProperty("value",node.has("amount")?node.get("amount").getAsDouble():.5);sorted.put(t,key);var a=new JsonArray();sorted.values().forEach(a::add);node.add("keys",a);});ImGui.sameLine();if(ImGui.button("Clear amount keys"))edit(o->o.getAsJsonArray("nodes").get(index).getAsJsonObject().remove("keys"));
            if(n.has("keys")){var keys=n.getAsJsonArray("keys");ImGui.textDisabled(keys.size()+" amount keys; linear interpolation");for(int k=0;k<keys.size();k++){final int keyIndex=k;var key=keys.get(k).getAsJsonObject();ImGui.pushID("key"+k);float[] t={key.get("time").getAsFloat()},v={key.get("value").getAsFloat()};float lo=k==0?0:keys.get(k-1).getAsJsonObject().get("time").getAsFloat()+.0001f,hi=k==keys.size()-1?1:keys.get(k+1).getAsJsonObject().get("time").getAsFloat()-.0001f;if(ImGui.sliderFloat("Key time",t,lo,hi,"%.3f",ImGuiSliderFlags.AlwaysClamp))edit(o->o.getAsJsonArray("nodes").get(index).getAsJsonObject().getAsJsonArray("keys").get(keyIndex).getAsJsonObject().addProperty("time",t[0]));if(ImGui.sliderFloat("Key amount",v,0,1,"%.3f",ImGuiSliderFlags.AlwaysClamp))edit(o->o.getAsJsonArray("nodes").get(index).getAsJsonObject().getAsJsonArray("keys").get(keyIndex).getAsJsonObject().addProperty("value",v[0]));if(ImGui.smallButton("Remove key")){edit(o->o.getAsJsonArray("nodes").get(index).getAsJsonObject().getAsJsonArray("keys").remove(keyIndex));ImGui.popID();break;}ImGui.popID();}}

            if(ImGui.button("Up")&&index>0)edit(o->Collections.swap(o.getAsJsonArray("nodes").asList(),index,index-1));ImGui.sameLine();if(ImGui.button("Down")&&index+1<nodes.size())edit(o->Collections.swap(o.getAsJsonArray("nodes").asList(),index,index+1));ImGui.sameLine();if(ImGui.button("Delete")){edit(o->o.getAsJsonArray("nodes").remove(index));ImGui.popID();break;}
        }ImGui.popID();}ImGui.textWrapped("Fresnel reconstructs surface normals from depth; images without depth use alpha edges. Intermediate views expose the latest two ping-pong buffers.");if(!RenderEffects.error().isBlank())status=RenderEffects.error();if(!status.isBlank())ImGui.textWrapped(status);
        }finally{ImGui.endChild();}
        }finally{ImGui.columns(1);}
    }catch(Exception e){status=e.getMessage();}finally{ImGui.end();}else ImGui.end();}
    void smoke(int stage,EffectFiles files)throws Exception{if(stage==0){open.set(true);json=Material.empty();json.getAsJsonArray("nodes").add(Material.node("gradient"));json.getAsJsonArray("nodes").add(Material.node("chromatic"));var pixel=Material.node("pixelate");pixel.addProperty("amount",1);pixel.addProperty("scale",4);json.getAsJsonArray("nodes").add(pixel);files.saveMaterial("smoke_material",json);if(!files.loadMaterial("smoke_material").equals(json))throw new IllegalStateException("Material export mismatch");world=true;sync();}else if(stage==1){if(preview==null||!status.isEmpty()||!RenderEffects.error().isEmpty()||RenderEffects.frames()==0)throw new IllegalStateException("Material workspace failed: "+status+RenderEffects.error());}else{open.set(false);close();if(RenderEffects.world()!=null)throw new IllegalStateException("Material workspace leaked world stack");}}
    private void sync(){RenderEffects.world(world?Material.compile(json):null);}
}
